import { useCallback } from 'react';
import api from '../api';
import { useApiResource, type LoadStatus } from './useApiResource';

// Catálogo de serviços do painel do admin: carga pelo GET /services/admin e as ações sobre
// a API (SPEC/2026-11-23-painel-servicos.md). As ações devolvem o serviço como o backend
// gravou e lançam o erro da API, para quem chamou mostrar a mensagem.

export type AdminService = {
  id: string;
  name: string;
  description: string | null;
  /** O backend serializa o Decimal como texto ("35.00"). */
  price: string;
  duration_minutes: number;
  is_active: boolean;
};

/** Campos da criação, já no formato da API. */
export type ServiceInput = Pick<AdminService, 'name' | 'description' | 'price' | 'duration_minutes'>;
/** Alteração parcial: só os campos que mudaram. */
export type ServiceChanges = Partial<ServiceInput & Pick<AdminService, 'is_active'>>;

export type ServicesStatus = LoadStatus;

/** Mesma ordem do backend: alfabética, sem diferenciar maiúsculas. */
function sortByName(services: AdminService[]): AdminService[] {
  return [...services].sort((a, b) => a.name.localeCompare(b.name, 'pt-BR', { sensitivity: 'base' }));
}

const loadServices = async () => (await api.get<AdminService[]>('/services/admin')).data;

export function useAdminServices() {
  const {
    data: services,
    setData: setServices,
    status,
    loadError,
    reload,
  } = useApiResource(loadServices, [] as AdminService[], 'Não foi possível carregar os serviços.');

  /** Põe o serviço gravado na lista, no lugar do antigo ou como novo, mantendo a ordem. */
  const store = useCallback((saved: AdminService) => {
    setServices((current) => sortByName([...current.filter((s) => s.id !== saved.id), saved]));
    return saved;
  }, []);

  const createService = useCallback(
    async (input: ServiceInput) => store((await api.post<AdminService>('/services', input)).data),
    [store],
  );

  const updateService = useCallback(
    async (id: string, changes: ServiceChanges) =>
      store((await api.put<AdminService>(`/services/${id}`, changes)).data),
    [store],
  );

  /** O DELETE só desativa (soft delete) e não devolve corpo: a lista marca o serviço. */
  const deactivateService = useCallback(async (id: string) => {
    await api.delete(`/services/${id}`);
    setServices((current) => current.map((s) => (s.id === id ? { ...s, is_active: false } : s)));
  }, []);

  const reactivateService = useCallback(
    (id: string) => updateService(id, { is_active: true }),
    [updateService],
  );

  return {
    services,
    status,
    loadError,
    reload,
    createService,
    updateService,
    deactivateService,
    reactivateService,
  };
}
import { useCallback } from 'react';
import api from '../api';
import type { UserRole } from '../utils/roles';
import { useApiResource } from './useApiResource';

// Usuários no painel do admin: a página da listagem (GET /auth/users) e as ações sobre um
// usuário (SPEC/2026-11-25-admin-usuarios.md). As ações devolvem o que o backend gravou e
// lançam o erro da API, para quem chamou mostrar a mensagem.

export type AdminUser = {
  id: string;
  email: string;
  full_name: string;
  phone: string | null;
  role: UserRole;
  is_active: boolean;
  email_verified: boolean;
  must_change_password: boolean;
};

export type UserPage = {
  users: AdminUser[];
  total: number;
  page: number;
  per_page: number;
  total_pages: number;
};

/** Busca no nome ou e-mail, filtro de perfil ('' = todos) e página, a partir de 1. */
export type UserFilters = { q: string; role: UserRole | ''; page: number };

export const PER_PAGE = 20;
const EMPTY: UserPage = { users: [], total: 0, page: 1, per_page: PER_PAGE, total_pages: 0 };
const LOAD_ERROR = 'Não foi possível carregar os usuários.';

export function useAdminUsers({ q, role, page }: UserFilters) {
  const load = useCallback(async () => {
    const params: Record<string, string | number> = { page, per_page: PER_PAGE };
    if (q.trim()) params.q = q.trim();
    if (role) params.role = role;
    return (await api.get<UserPage>('/auth/users', { params })).data;
  }, [q, role, page]);

  const { data, setData, status, loadError, reload } = useApiResource(load, EMPTY, LOAD_ERROR);

  /** Troca o usuário da página pelo que o backend devolveu. */
  const store = useCallback((saved: AdminUser) => {
    setData((current) => ({ ...current, users: current.users.map((u) => (u.id === saved.id ? saved : u)) }));
    return saved;
  }, []);

  const changeRole = useCallback(
    async (id: string, newRole: UserRole) =>
      store((await api.put<AdminUser>(`/auth/users/${id}/role`, { role: newRole })).data),
    [store],
  );

  const setActive = useCallback(
    async (id: string, isActive: boolean) =>
      store((await api.put<AdminUser>(`/auth/users/${id}/status`, { is_active: isActive })).data),
    [store],
  );

  /**
   * Gera a senha temporária e a devolve para ser mostrada uma vez: ela não fica guardada aqui.
   * O usuário passa a aparecer com a troca de senha pendente.
   */
  const generateTemporaryPassword = useCallback(async (id: string) => {
    const response = await api.post<{ temporary_password: string }>(`/auth/users/${id}/temporary-password`);
    setData((current) => ({
      ...current,
      users: current.users.map((u) => (u.id === id ? { ...u, must_change_password: true } : u)),
    }));
    return response.data.temporary_password;
  }, []);

  return { ...data, status, loadError, reload, changeRole, setActive, generateTemporaryPassword };
}
import { useCallback, useEffect, useState } from 'react';
import { apiErrorMessage } from '../utils/apiError';

// Carga de dados da API com "carregando", erro em português e "Tentar de novo". Usado pelo
// painel de serviços (SPEC/2026-11-23-painel-servicos.md) e por Meus agendamentos
// (SPEC/2026-11-25-meus-agendamentos.md). `setData` deixa quem usa atualizar a lista depois
// de uma ação, sem carregar de novo. `load` precisa ser estável (função do módulo ou
// useCallback): uma função nova a cada renderização carregaria de novo a cada renderização.

export type LoadStatus = 'loading' | 'ready' | 'error';

export function useApiResource<T>(load: () => Promise<T>, initial: T, fallbackError: string) {
  const [data, setData] = useState<T>(initial);
  const [status, setStatus] = useState<LoadStatus>('loading');
  const [loadError, setLoadError] = useState('');
  // Mudar o número pede uma nova carga ("Tentar de novo").
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let active = true;
    setStatus('loading');
    load()
      .then((loaded) => {
        if (!active) return;
        setData(loaded);
        setStatus('ready');
      })
      .catch((error) => {
        if (!active) return;
        setLoadError(apiErrorMessage(error, fallbackError));
        setStatus('error');
      });
    return () => {
      active = false;
    };
  }, [attempt, load, fallbackError]);

  const reload = useCallback(() => setAttempt((n) => n + 1), []);

  return { data, setData, status, loadError, reload };
}
import { useCallback, useState } from 'react';
import { apiErrorMessage } from '../utils/apiError';

// Ação sobre uma linha de uma tabela do painel: a linha fica ocupada enquanto a ação roda, e o
// resultado aparece no topo, como mensagem ou erro da API. Usado pelos painéis de serviços
// (SPEC/2026-11-23-painel-servicos.md) e de usuários (SPEC/2026-11-25-admin-usuarios.md).

export function useRowAction() {
  const [busyId, setBusyId] = useState<string | null>(null);
  const [message, setMessage] = useState('');
  const [actionError, setActionError] = useState('');

  const clear = useCallback(() => {
    setMessage('');
    setActionError('');
  }, []);

  /** Roda `action` com a linha `id` ocupada. Devolve o resultado, ou undefined se falhou. */
  const run = useCallback(
    async <T,>(id: string, action: () => Promise<T>, done: string): Promise<T | undefined> => {
      clear();
      setBusyId(id);
      try {
        const result = await action();
        setMessage(done);
        return result;
      } catch (error) {
        setActionError(apiErrorMessage(error, 'Não foi possível concluir a ação.'));
        return undefined;
      } finally {
        setBusyId(null);
      }
    },
    [clear],
  );

  return { busyId, message, actionError, run, clear, setMessage };
}

