/** Campos alterados em relação ao serviço salvo. O preço é comparado pelo valor. */
export function serviceChanges(service: AdminService, fields: ServiceFields): ServiceChanges {
  const input = serviceInput(fields);
  const changes: ServiceChanges = {};
  if (input.name !== service.name) changes.name = input.name;
  if (input.description !== (service.description || null)) changes.description = input.description;
  if (Number(input.price) !== Number(service.price)) changes.price = input.price;
  if (input.duration_minutes !== service.duration_minutes) changes.duration_minutes = input.duration_minutes;
  return changes;
}

function initialFields(service?: AdminService): ServiceFields {
  if (!service) return { name: '', description: '', price: '', duration: '' };
  return {
    name: service.name,
    description: service.description ?? '',
    price: priceToInput(service.price),
    duration: String(service.duration_minutes),
  };
}

const ServiceForm = ({ service, onSave, onCancel }: Props) => {
  const [fields, setFields] = useState<ServiceFields>(() => initialFields(service));
  const [error, setError] = useState('');
  const [info, setInfo] = useState('');
  const [saving, setSaving] = useState(false);

  const editing = service !== undefined;
  const title = editing ? 'Editar serviço' : 'Novo serviço';
  const set = (key: keyof ServiceFields) => (
    event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>,
  ) => setFields((current) => ({ ...current, [key]: event.target.value }));

  const handleSubmit = async (event: React.FormEvent) => {
    event.preventDefault();
    setError('');
    setInfo('');

    const problem =
      validateServiceName(fields.name) ?? validatePrice(fields.price) ?? validateDuration(fields.duration);
    if (problem) {
      setError(problem);
      return;
    }

    const data = editing ? serviceChanges(service, fields) : serviceInput(fields);
    if (Object.keys(data).length === 0) {
      setInfo('Nada mudou.');
      return;
    }

    setSaving(true);
    try {
      // Quem chamou fecha o formulário depois de salvar: daqui em diante ele some.
      await onSave(data);
    } catch (err) {
      setError(apiErrorMessage(err, 'Não foi possível salvar o serviço.'));
      setSaving(false);
    }
  };

  return (
    <form className={styles.form} onSubmit={handleSubmit} noValidate aria-label={title}>
      <h3>{title}</h3>

      <div className={`${styles.field} ${styles.wide}`}>
        <label htmlFor="servico-nome">Nome</label>
        <input id="servico-nome" value={fields.name} onChange={set('name')} />
      </div>

      <div className={`${styles.field} ${styles.wide}`}>
        <label htmlFor="servico-descricao">Descrição (opcional)</label>
        <textarea id="servico-descricao" rows={2} value={fields.description} onChange={set('description')} />
      </div>

      <div className={styles.field}>
        <label htmlFor="servico-preco">Preço (R$)</label>
        <input id="servico-preco" inputMode="decimal" placeholder="35,00" value={fields.price} onChange={set('price')} />
      </div>

      <div className={styles.field}>
        <label htmlFor="servico-duracao">Duração (min)</label>
        <input id="servico-duracao" inputMode="numeric" placeholder="30" value={fields.duration} onChange={set('duration')} />
      </div>

      {error && <p className={styles.error} role="alert">{error}</p>}
      {info && <p className={styles.info} role="status">{info}</p>}

      <div className={styles.actions}>
        <button type="button" className={styles.secondary} onClick={onCancel} disabled={saving}>
          Cancelar
        </button>
        <button type="submit" className={styles.primary} disabled={saving}>
          {saving ? 'Salvando...' : 'Salvar serviço'}
        </button>
      </div>
    </form>
  );
};

export default ServiceForm;
import shared from '../../pages/AdminShared.module.css';
import ConfirmButton from '../ConfirmButton';
import type { AdminService } from '../../hooks/useAdminServices';
import { formatPrice } from '../../utils/serviceValidation';
import styles from './Services.module.css';

// Uma linha da tabela de serviços do painel (SPEC/2026-11-23-painel-servicos.md).
// "Desativar" pede confirmação na própria linha (ConfirmButton). "Reativar" não pede.

type Props = {
  service: AdminService;
  /** Uma ação desta linha está em andamento: os botões ficam desabilitados. */
  busy: boolean;
  onEdit: (service: AdminService) => void;
  onDeactivate: (service: AdminService) => void;
  onReactivate: (service: AdminService) => void;
};

const ServiceRow = ({ service, busy, onEdit, onDeactivate, onReactivate }: Props) => {
  const edit = (
    <button className={shared.btnIcon} onClick={() => onEdit(service)} disabled={busy}>
      Editar
    </button>
  );
  const actions = service.is_active ? (
    <ConfirmButton label="Desativar" question="Desativar este serviço?" onConfirm={() => onDeactivate(service)} busy={busy}>
      {edit}
    </ConfirmButton>
  ) : (
    <>
      {edit}
      <button className={shared.btnIcon} onClick={() => onReactivate(service)} disabled={busy}>
        Reativar
      </button>
    </>
  );

  return (
    <tr className={service.is_active ? undefined : styles.inactive} aria-label={service.name}>
      <td style={{ color: '#fff', fontWeight: 500 }}>
        {service.name}
        {service.description && <span className={styles.description}>{service.description}</span>}
      </td>
      <td>{service.duration_minutes} min</td>
      <td>{formatPrice(service.price)}</td>
      <td>
        <span className={`${styles.badge} ${service.is_active ? styles.badgeActive : styles.badgeInactive}`}>
          {service.is_active ? 'Ativo' : 'Desativado'}
        </span>
      </td>
      <td>{actions}</td>
    </tr>
  );
};

export default ServiceRow;
import React, { useState } from 'react';
import shared from '../../pages/AdminShared.module.css';
import { ROLE_LABELS, ROLES, type UserRole } from '../../utils/roles';

// Busca por nome ou e-mail e filtro de perfil do painel de usuários
// (SPEC/2026-11-25-admin-usuarios.md). A busca vai ao enviar o formulário, não a cada tecla.

type Props = {
  role: UserRole | '';
  onSearch: (q: string) => void;
  onRoleChange: (role: UserRole | '') => void;
};

const UserFilters = ({ role, onSearch, onRoleChange }: Props) => {
  const [draft, setDraft] = useState('');

  const submit = (event: React.FormEvent) => {
    event.preventDefault();
    onSearch(draft);
  };

  return (
    <form className={shared.filters} onSubmit={submit} role="search">
      <input
        type="search"
        aria-label="Buscar por nome ou e-mail"
        placeholder="Nome ou e-mail"
        value={draft}
        maxLength={100}
        onChange={(e) => setDraft(e.target.value)}
      />
      <button type="submit" className={shared.btnIcon}>Buscar</button>
      <select aria-label="Perfil" value={role} onChange={(e) => onRoleChange(e.target.value as UserRole | '')}>
        <option value="">Todos os perfis</option>
        {ROLES.map((r) => (
          <option key={r} value={r}>{ROLE_LABELS[r]}</option>
        ))}
      </select>
    </form>
  );
};

export default UserFilters;
import shared from '../../pages/AdminShared.module.css';
import ConfirmButton from '../ConfirmButton';
import type { AdminUser } from '../../hooks/useAdminUsers';
import { ROLE_LABELS, ROLES, type UserRole } from '../../utils/roles';
import styles from '../services/Services.module.css';

// Uma linha da tabela de usuários do painel (SPEC/2026-11-25-admin-usuarios.md). Desativar e
// gerar a senha temporária pedem confirmação na própria linha (ConfirmButton); ativar não pede.
// Na linha do próprio admin não há ações: o backend recusaria.

type Props = {
  user: AdminUser;
  /** A linha é a do admin logado. */
  isSelf: boolean;
  /** Uma ação desta linha está em andamento: os controles ficam desabilitados. */
  busy: boolean;
  onChangeRole: (user: AdminUser, role: UserRole) => void;
  onSetActive: (user: AdminUser, isActive: boolean) => void;
  onGeneratePassword: (user: AdminUser) => void;
};

const UserActions = ({ user, busy, onSetActive, onGeneratePassword }: Omit<Props, 'isSelf' | 'onChangeRole'>) => {
  if (!user.is_active) {
    return (
      <button className={shared.btnIcon} onClick={() => onSetActive(user, true)} disabled={busy}>
        Ativar
      </button>
    );
  }
  return (
    <>
      <ConfirmButton
        label="Gerar senha temporária"
        question="Gerar uma senha temporária? A atual deixa de valer."
        onConfirm={() => onGeneratePassword(user)}
        busy={busy}
      />
      <ConfirmButton label="Desativar" question="Desativar esta conta?" onConfirm={() => onSetActive(user, false)} busy={busy} />
    </>
  );
};

const UserRow = ({ user, isSelf, busy, onChangeRole, onSetActive, onGeneratePassword }: Props) => (
  <tr className={user.is_active ? undefined : styles.inactive} aria-label={user.full_name}>
    <td style={{ color: '#fff', fontWeight: 500 }}>
      {user.full_name}
      <span className={styles.description}>{user.email}</span>
    </td>
    <td>
      {isSelf ? (
        ROLE_LABELS[user.role]
      ) : (
        <select
          aria-label={`Perfil de ${user.full_name}`}
          value={user.role}
          onChange={(e) => onChangeRole(user, e.target.value as UserRole)}
          disabled={busy}
        >
          {ROLES.map((role) => (
            <option key={role} value={role}>{ROLE_LABELS[role]}</option>
          ))}
        </select>
      )}
    </td>
    <td>
      <span className={`${styles.badge} ${user.is_active ? styles.badgeActive : styles.badgeInactive}`}>
        {user.is_active ? 'Ativo' : 'Desativado'}
      </span>
      {user.must_change_password && <span className={styles.description}>Troca de senha pendente</span>}
    </td>
    <td>
      {isSelf ? (
        <span className={styles.description}>Você</span>
      ) : (
        <UserActions user={user} busy={busy} onSetActive={onSetActive} onGeneratePassword={onGeneratePassword} />
      )}
    </td>
  </tr>
);

export default UserRow;

