  # Duplicação em src/, só como relatório: este job não falha por duplicação (#41).
  duplicacao:
    name: Duplicação (jscpd, relatório)
    runs-on: ubuntu-latest
    env:
      JSCPD_VERSION: 5.4.3
    steps:
      - uses: actions/checkout@v4

      - uses: actions/setup-node@v4
        with:
          node-version: "22"

